const actor = game.user.character;
if (!actor) {
    ui.notifications.warn(game.i18n.localize("FQCARDENGINE.NoOwnedCharacter"));
} else {
    // `render(true)` force l'affichage : la feuille déjà ouverte est démasquée et
    // ramenée au premier plan plutôt que redessinée derrière les autres fenêtres.
    actor.sheet.render(true);
}
